<?php

namespace App\Content\Repository;

use Doctrine\ORM\EntityRepository;
use App\Appearance\Entity\Menu;

/**
 * HomePageRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class HomePageRepository extends EntityRepository
{

    public function globalOptionHome($user)
    {
        $em = $this->getEntityManager();

        $reEntity = $em->getRepository(\App\Content\Entity\HomePage::class)->findOneBy(['user'=>$user]);
        if(empty($reEntity) && $user){

            $entity = New HomePage();
            $entity->setUser($user);
            $entity->setName("Home");
            $em->persist($entity);

            $entity = New Menu();
            $entity->setMenu('Home');
            $entity->setMenuSlug('home');
            $entity->setUser($user);
            $entity->setDefaultMenu(true);
            $em->persist($entity);

            $em->flush();
        }


    }


}
